const prev = $('Orquestador 3 - Asignar Agente 2 y catalogo').first().json;
const out = $input.first().json.output || {};
const dur = Date.now() - prev._t_prep;
const cat = prev.catalogo;
const norm = function (x) { return String(x || '').toLowerCase().replace('producto', '').trim(); };
const adv = Array.isArray(out.advertencias) ? out.advertencias.slice() : [];
const items = Array.isArray(out.items) ? out.items : [];
const errores = [];
const verificados = [];
if (out.caso_id !== prev.caso_id) errores.push('caso_id inconsistente en Agente 2: ' + out.caso_id);
if (out.fuente !== cat.fuente) errores.push('Fuente del catalogo no conservada por el Agente 2: ' + out.fuente);
for (const p of prev.agente1.productos) {
  const k = norm(p.nombre);
  const c = cat.productos[k];
  const qty = Number(p.cantidad);
  if (!c) { errores.push('Producto inexistente en el catalogo: ' + p.nombre); continue; }
  if (qty > c.inventario) { errores.push('Sin inventario suficiente para ' + c.nombre + ': solicitado ' + qty + ', disponible ' + c.inventario); continue; }
  const it = items.find(function (i) { return norm(i.producto) === k; });
  if (!it) { errores.push('El Agente 2 no devolvio el producto ' + c.nombre); continue; }
  if (Number(it.precio_unitario) !== c.precio) errores.push('Precio reportado por Agente 2 para ' + c.nombre + ' (' + it.precio_unitario + ') difiere del catalogo (' + c.precio + ')');
  if (Number(it.inventario) !== c.inventario) errores.push('Inventario reportado por Agente 2 para ' + c.nombre + ' difiere del catalogo');
  if (it.existe !== true || it.disponible !== true) errores.push('El Agente 2 no confirmo existencia/disponibilidad de ' + c.nombre);
  verificados.push({ producto: c.nombre, cantidad: qty, precio_unitario: c.precio, moneda: cat.moneda, inventario: c.inventario, fuente: cat.fuente });
}
const ok = errores.length === 0;
const motivo = ok ? null : errores.join('; ');
const trazaAg = {
  caso_id: prev.caso_id, agente: 'AGENTE_2_CATALOGO_INVENTARIOS', etapa: 'consulta_catalogo_e_inventarios',
  estado: ok ? 'COMPLETADO' : 'DETENIDO',
  resultado: ok ? { items: verificados } : motivo,
  fuentes: [cat.fuente], advertencias: adv, duracion_ms: dur,
  referencia_consumo: { execution_id: $execution.id, nodo: 'Agente 2 - Catalogo e inventarios', modelo: 'gpt-5-mini (Gateway credits)', tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Tokens/costo no expuestos por el nodo AI Agent: pendiente de configurar.' }
};
const trazaOrq = {
  caso_id: prev.caso_id, agente: 'ORQUESTADOR', etapa: 'revision_agente_2',
  estado: ok ? 'COMPLETADO' : 'DETENIDO',
  resultado: ok ? 'Productos existentes, con inventario suficiente y precios identicos al catalogo autorizado. Se calcula la cotizacion.' : 'Proceso detenido: ' + motivo,
  fuentes: [cat.fuente], advertencias: [], duracion_ms: 0,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Logica determinista.' }
};
return [{ json: Object.assign({}, prev, {
  estado_flujo: ok ? 'OK' : 'DETENIDO', motivo_detencion: motivo,
  agente2: out, items_verificados: verificados,
  advertencias: prev.advertencias.concat(adv),
  trazas: prev.trazas.concat([trazaAg, trazaOrq]),
  presupuesto: Object.assign({}, prev.presupuesto, { llamadas_ia_realizadas: prev.presupuesto.llamadas_ia_realizadas + 1 }),
  _t_prep: Date.now()
}) }];

const s = $input.first().json;
const r2 = function (n) { return Math.round(n * 100) / 100; };
const lineas = s.items_verificados.map(function (i) {
  return { producto: i.producto, cantidad: i.cantidad, precio_unitario: i.precio_unitario, subtotal: r2(i.cantidad * i.precio_unitario) };
});
const subtotal = r2(lineas.reduce(function (a, l) { return a + l.subtotal; }, 0));
const cotizacion = {
  caso_id: s.caso_id, lineas: lineas, subtotal: subtotal, impuestos: 0, envio: 0, descuentos: 0,
  total: subtotal, moneda: s.catalogo.moneda, fuente: s.catalogo.fuente
};
const trazaOrq = {
  caso_id: s.caso_id, agente: 'ORQUESTADOR', etapa: 'calculo_determinista',
  estado: 'COMPLETADO',
  resultado: 'Subtotales y total calculados en Code (sin impuestos, envio ni descuentos): total ' + subtotal + ' ' + s.catalogo.moneda,
  fuentes: [s.catalogo.fuente], advertencias: [], duracion_ms: 0,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Calculo determinista: no consume tokens.' }
};
return [{ json: Object.assign({}, s, { cotizacion: cotizacion, trazas: s.trazas.concat([trazaOrq]), _t_prep: Date.now() }) }];

