  estado: exito ? 'COMPLETADO' : estadoFinal,
  resultado: exito ? 'Caso completo: 4 agentes ejecutados, revision tecnica aprobada. Estado PENDIENTE_APROBACION; aprobacion humana PENDIENTE.' : 'Caso cerrado sin exito: ' + (s.motivo_detencion || estadoFinal),
  fuentes: ['trazas del caso'], advertencias: [], duracion_ms: ahora - s._t_prep,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Logica determinista.' }
};
const advertencias = s.advertencias.slice();
advertencias.push('Consumo (tokens/costo) no disponible: pendiente de configurar. Presupuesto de ' + s.limite_costo_usd + ' USD no verificable automaticamente.');
if (!exito && s.motivo_detencion) advertencias.push(s.motivo_detencion);
const lineas = cot ? cot.lineas : [];
const cantidades = {};
const precios = {};
lineas.forEach(function (l) { cantidades[l.producto] = l.cantidad; precios[l.producto] = l.precio_unitario; });
const resultado = {
  caso_id: s.caso_id,
  estado_final: estadoFinal,
  productos: lineas.map(function (l) { return l.producto; }),
  cantidades: cantidades,
  precios: precios,
  detalle_lineas: lineas,
  importe_total: exito ? cot.total : null,
  moneda: cot ? cot.moneda : null,
  revision_tecnica: s.revision_tecnica || { dictamen: 'NO_EJECUTADA', hallazgos: [s.motivo_detencion || 'Proceso detenido antes del control de calidad'] },
aprobacion_humana: exito ? 'PENDIENTE' : 'NO_SOLICITADA',
  advertencias: advertencias,
  modo: s.modo,
  agentes_ejecutados: agentesCompletados,
  presupuesto: s.presupuesto,
  duracion_total_ms: ahora - s._t_inicio,
  trazas: s.trazas.concat([cierreTraza])
};
return [{ json: resultado }];

const evento = $input.first().json;
const mensaje = evento.message;

// Usuario autorizado para las pruebas
const usuariosPermitidos = []; // CONFIGURAR IDs autorizados solo en la instancia privada; vacío deniega acceso.

if (!mensaje || !mensaje.from || !mensaje.chat) {
  throw new Error("Evento de Telegram inválido");
}

const usuarioId = mensaje.from.id;
const chatId = mensaje.chat.id;

if (!usuariosPermitidos.includes(usuarioId)) {
  throw new Error("Usuario no autorizado");
}

if (typeof mensaje.text !== "string" ||
    !mensaje.text.trim()) {
  throw new Error("Debes enviar un mensaje de texto");
}

let solicitud = mensaje.text.trim();

// Quitar /nuevo o /new, conservando la autorización del usuario
solicitud = solicitud.replace(
  /^\/(?:nuevo|new)(?:@\w+)?(?:\s+|$)/i,
  ""
).trim();

if (!solicitud || solicitud.length > 1000) {
  throw new Error("Solicitud vacía o demasiado larga");
}

const idEvento = evento.update_id;

if (!Number.isSafeInteger(idEvento)) {
  throw new Error("Identificador de evento inválido");
}

return [{
